mapper.select:
SELECT tpc.contract_duration
FROM tenant_precontract_check tpc
WHERE tpc.contract_chat_id = #{contractChatId}

mapper.update:
UPDATE contract_chat
SET status = #{step}
WHERE contract_chat_id = #{contractChatId}

UPDATE electronic_signature
SET owner_tax_signature_file_url = #{url}, owner_tax_file_hash = #{hashKey}, owner_tax_signed_at = NOW()
    WHERE contract_id = #{finalContractId}

mapper.select:
SELECT es.owner_tax_signature_file_url
FROM electronic_signature es
WHERE es.contract_id = #{finalContractId}

SELECT deposit_adjustment
FROM tenant_precontract_check
WHERE contract_chat_id = #{contractChatId}
